// Get the current flag value, default to 1 if undefined
var flag = flow.get('Tflag') || flow.get('Hflag');
var hflag = flow.get('Hflag') || 0;
var tflag = flow.get('Tflag') || 0;

// Debugging to track flag state
node.warn(`Before If flag: ${flag}`);

if (flag === 1) {
    // Parse the input as a number
    var value = parseInt(msg.payload.content, 10);

    if (isNaN(value)) {
        // Handle invalid input
        msg.payload = {
            chatId: msg.payload.chatId,
            type: 'message',
            content: `Invalid input. Please enter a numeric value.`
        };
    } else if (tflag === 1){
        // Store the value and disable further input
        flow.set('Tflag', 0);
        flow.set('Tvalue', 1);
        flow.set('storedValue', value);
        flow.set('flag', 0); // Set flag to 0 to prevent further inputs

        // Debugging to confirm flag update
        node.warn(`Flag after storing value: ${flow.get('flag')} and tflag: ${flow.get('Hflag')}`);

        msg.payload = {
            chatId: msg.payload.chatId,
            type: 'message',
            content: `Value ${value} has been saved as new Temperature Threshold.`
        };
    } else {
        // Store the value and disable further input
        flow.set('Hflag', 0);
        flow.set('Hvalue', 1);
        flow.set('storedValue', value);
        flow.set('flag', 0); // Set flag to 0 to prevent further inputs

        // Debugging to confirm flag update
        node.warn(`Flag after storing value: ${flow.get('flag')} and hflag: ${flow.get('Hflag')}`);

        msg.payload = {
            chatId: msg.payload.chatId,
            type: 'message',
            content: `Value ${value} has been saved as new Humidity Threshold.`
        };
    }
} else {
    // Reject any further input
    msg.payload = {
        chatId: msg.payload.chatId,
        type: 'message',
        content: `Invalid Entry! Input is no longer allowed.`
    };

    // Debugging to confirm rejection
    node.warn(`Rejected input because flag = ${flag}`);
}

return msg;

