var temp = flow.get("avgTempVal");
var humi = flow.get("avgHumiVal");
var currHumi = global.get("currHumi");
var currTemp = global.get("currTemp");
msg.payload = `Welcome to Weather Dashboard. Today's Current Temperature and Humidity are ${currTemp}°C and ${currHumi} % respectively. Today's Average Temperature is ${temp} 
                while the Average Humidity is ${humi}.`
