return msg;

var avgTempMsg = flow.get("avgTempMessage");
msg.payload = `${avgTempMsg}`;
return msg;

// Retrieving the previous temperatures from flow context and 0 if undefined
var previousTemp = flow.get('previousTemp') || 0;

// Initializing counters and 0 if undefined
var increaseCount = flow.get('increaseCount') || 0;
var decreaseCount = flow.get('decreaseCount') || 0;

// Retrieving the current temperature from payload
var currentTemp = msg.payload.temperature;

// Hot temperature alert
if (currentTemp > 24) {
    // If temp increases or remains same
    if (currentTemp >= previousTemp) {

        // increment the counter if temp increases or remains same
        increaseCount += 1;
        decreaseCount = 0; // Reset the decrease counter

        // Debug messages for Current/Previous Temp and increaseCount
        node.warn(`currentTemp: ${currentTemp} and previousTemp: ${previousTemp}`)
        node.warn(`increaseCount: ${increaseCount}`);

        // Check if the temperature has increased or remains same for 5 times or more consecutively
        if (increaseCount >= 5) {

            flow.set('increaseCount', increaseCount); // Set the increase counter after alert
            flow.set('previousTemp', currentTemp);

            if (increaseCount % 5 == 0) {
                msg.payload = `ALERT: Hot Warning!! Temperature is ${currentTemp}°C for ${increaseCount * 20} Seconds. Please check the Heater!!`;
                return msg; // Send the alert message
            }
        }
    } else {
        // Reset the increase counter if temperature starts decreasing
        increaseCount = 0;
        flow.set('increaseCount', increaseCount);
    }
} else{
    increaseCount = 0;
    flow.set('increaseCount', increaseCount);

}

// Cold temperature alert
if (currentTemp < 11) {
    // If temp decreases or remains same
    if (currentTemp <= previousTemp) {

        // Temperature is decreasing, increment the decrease counter
        decreaseCount += 1;
        increaseCount = 0; // Reset the increase counter

        // Debug messages for Current/Previous Temp and decreaseCount
        node.warn(`currentTemp: ${currentTemp} and previousTemp: ${previousTemp}`)
        node.warn(`decreaseCount: ${decreaseCount}`)

        // Check if the temperature has decreased remains same for 5 times or more consecutively
        if (decreaseCount >= 5) {
            flow.set('decreaseCount', decreaseCount); // Reset the decrease counter after alert
            flow.set('previousTemp', currentTemp);

            if (decreaseCount % 5 == 0) {
                msg.payload = `ALERT: Cold Warning!! Temperature is ${currentTemp}°C for ${decreaseCount * 20} Seconds. Please check the Heater!!`;
                return msg; // Send the alert message
            }
        }
    } else {
        // Reset the decrease counter if temperature stops decreasing
        decreaseCount = 0;
        flow.set('decreaseCount', decreaseCount);
    }
} else{
    decreaseCount = 0;
    flow.set('decreaseCount', decreaseCount);
}

// Store the current temperature and updated counters in the flow context
flow.set('previousTemp', currentTemp);
flow.set('increaseCount', increaseCount);
flow.set('decreaseCount', decreaseCount);

// No alert if conditions are not met
return null;

// Extract temperature from the message
var temp = msg.payload;

// For Test
// var temp = msg.payload.temperature;

// Save it to the flow variable 'currentTemp'
flow.set('currentTemp', temp);

msg.payload = { temperature: temp }
return msg;

// Retrieve the counter from flow context (default to 0)
var counter = flow.get('counter') || 0;

// Create a list of temperatures to send
var temperatureSequence = [25, 26, 27, 28, 29, 30, 22, 30, 8, 7, 7, 7, 7, 7, 12, 4];
// var temperatureSequence = [8, 7, 7, 7, 7, 7, 5, 5, 5, 5, 4, 12, 12, 4];

// Get the current temperature based on the counter
var temperature = temperatureSequence[counter];

// Increment the counter for the next cycle
counter = (counter + 1) % temperatureSequence.length; // Loop back after the last value

// Store the updated counter in flow context
flow.set('counter', counter);

// Set the payload to the current temperature
msg.payload = {temperature};

// Return the modified message
return msg;
